1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	};
8	
9	type Item = { type: string };
10	
11	const RUNE_BLOCK_SIZE = 3;
12	const RUNE_BLOCK_PRICE = 60;
13	
14	export const basePremium = (items: Item[]): number => {
15	  const runeCount = items.filter((item) => item.type === "rune").length;
16	  if (runeCount === RUNE_BLOCK_SIZE) return RUNE_BLOCK_PRICE;
17	  return items.reduce((sum, item) => sum + priceList[item.type], 0);
18	};
19	
20	export const runScenario = (_scenario: unknown): unknown => undefined;
