1	import { describe, it, expect } from "vitest";
2	import { basePremium, runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums for main items (price list) ---
6	  it("basePremium: a sword → 100 G base premium", () => {
7	    expect(basePremium([{ type: "sword" }])).toBe(100);
8	  });
9	  it("basePremium: an amulet → 60 G base premium", () => {
10	    expect(basePremium([{ type: "amulet" }])).toBe(60);
11	  });
12	  it("basePremium: a staff → 80 G base premium", () => {
13	    expect(basePremium([{ type: "staff" }])).toBe(80);
14	  });
15	  it("basePremium: a potion → 40 G base premium", () => {
16	    expect(basePremium([{ type: "potion" }])).toBe(40);
17	  });
18	
19	  // --- Component pricing and the building block of 3 alike components ---
20	  it("basePremium: a single rune → 25 G base premium", () => {
21	    expect(basePremium([{ type: "rune" }])).toBe(25);
22	  });
23	  it("basePremium: 2 runes → 50 G base premium (no block)", () => {
24	    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
25	  });
26	  it("basePremium: 3 runes → 60 G base premium (block applies)", () => {
27	    expect(
28	      basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }]),
29	    ).toBe(60);
30	  });
31	  it("basePremium: 4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
32	    expect(
33	      basePremium([
34	        { type: "rune" },
35	        { type: "rune" },
36	        { type: "rune" },
37	        { type: "rune" },
38	      ]),
39	    ).toBe(100);
40	  });
41	  it.todo("basePremium: 7 runes → 175 G base premium");
42	
43	  // --- "Alike" components: block requires same type ---
44	  it.todo("basePremium: 2 runes + 1 moonstone → 75 G base premium (no block: different types)");
45	  it.todo("basePremium: 3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
46	
47	  // --- Processing fee and empty policy ---
48	  it.todo("quote: empty item list → premium 5 G (only the processing fee)");
49	
50	  // --- Individual premium modifiers ---
51	  it.todo("quote: newcomer with a cursed sword (0 yrs, steel, enchantment 3) → premium 165 G");
52	  it.todo("quote: high-enchantment surcharge applies at exactly enchantment 5");
53	  it.todo("quote: enchantment 4 → no high-enchantment surcharge");
54	  it.todo("quote: cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");
55	  it.todo("quote: customer with exactly 2 years → loyalty discount applies");
56	
57	  // --- Modifier scope on multi-item policies ---
58	  it.todo("quote: cursed surcharge is 50% of the cursed item's base premium, not of the policy total");
59	  it.todo("quote: each item in a quote is treated as a first insurance regardless of customer history");
60	
61	  // --- Integration examples ---
62	  it.todo("quote: long-standing customer's second contract, cursed sword enchantment 7 (3 yrs) → premium 160 G");
63	
64	  // --- Rounding in the MHPCO's favor ---
65	  it.todo("quote: a premium that yields 197.5 G → final premium 198 G (rounded up)");
66	  it.todo("claim: a payout that yields 350.5 G → final payout 350 G (rounded down)");
67	
68	  // --- Claim processing: standard reimbursement ---
69	  it.todo("claim: regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
70	  it.todo("claim: rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
71	
72	  // --- Claim processing: enchantment threshold vs dragon material ---
73	  it.todo("claim: dragon-material sword enchantment 8, damage 1000 G → payout 400 G (50% then deductible)");
74	  it.todo("claim: dragon-material sword enchantment 5, damage 800 G → payout 700 G (full then deductible)");
75	  it.todo("claim: steel sword enchantment 9, damage 1000 G → payout 400 G (50% then deductible)");
76	  it.todo("claim: dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50% rule wins)");
77	
78	  // --- Deductible per damage event ---
79	  it.todo("claim: dragon attack damages sword 500 G and amulet 300 G → payout 600 G (deductible per item)");
80	
81	  // --- Multiple items of the same type ---
82	  it.todo("claim: two swords, damages to both → each entry is a separate damage with its own deductible");
83	  it.todo("claim: more damage entries of a type than the policy covers → whole claim rejected (throws)");
84	
85	  // --- Insurance sum and cap ---
86	  it.todo("claim: cursed sword cap is 2000 G, based on the unmodified insurance value");
87	  it.todo("claim: sword + amulet → insurance sum 1600 G, cap 3200 G");
88	  it.todo("claim: sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
89	
90	  // --- Cap exhaustion across successive claims ---
91	  it.todo("claim: sword (cap 2000 G), two 1500 G claims → 1400 G (rem 600), then 600 G (rem 0)");
92	
93	  // --- Error handling / edge cases ---
94	  it.todo("quote: unknown item type (e.g. broomstick) → throws (non-zero exit, error to stderr)");
95	  it.todo("claim: damage entry for an item not in the policy → throws");
96	  it.todo("claim: damage entry with a negative amount → throws");
97	
98	  // --- End-to-end multi-step scenario (CLI shape) ---
99	  it.todo("runScenario: quote then claim produces results in the same order as steps");
100	});
